func schema_pkg_apis_ome_v1beta1_InferenceServiceSpec(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "InferenceServiceSpec is the top level type for this resource",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"deploymentMode": {
						SchemaProps: spec.SchemaProps{
							Description: "DeploymentMode selects the dispatch backend that drives every Component on this InferenceService. When set, it propagates to the Engine, Decoder, and Router resolver at read-time without mutating per-Component annotations — `kubectl get -o yaml` stays clean. A per-Component `ome.io/deploymentMode` annotation still wins as an explicit override (the escape hatch is preserved for backward compat and mixed-mode experiments).\n\nValid values:\n  - \"OMENative\"     — Native lifecycle-managed pods (also\n    handles multi-node serving when Leader/Worker are present)\n  - \"RawDeployment\" — Kubernetes Deployment/HPA-backed dispatch",
							Type:        []string{"string"},
							Format:      "",
						},
					},
					"engine": {
						SchemaProps: spec.SchemaProps{
							Description: "Engine defines the serving engine spec This provides detailed container and pod specifications for model serving. It allows defining the model runner (container spec), as well as complete pod specifications including init containers, sidecar containers, and other pod-level configurations. Engine can also be configured for multi-node deployments using leader and worker specifications.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.EngineSpec"),
						},
					},
					"decoder": {
						SchemaProps: spec.SchemaProps{
							Description: "Decoder defines the decoder spec This is specifically used for PD (Prefill-Decode) disaggregated serving deployments. Similar to Engine in structure, it allows for container and pod specifications, but is only utilized when implementing the disaggregated serving pattern to separate the prefill and decode phases of inference.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.DecoderSpec"),
						},
					},
					"model": {
						SchemaProps: spec.SchemaProps{
							Description: "Model defines the model to be used for inference, referencing either a BaseModel or a custom model. This allows models to be managed independently of the serving configuration.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.ModelRef"),
						},
					},
					"runtime": {
						SchemaProps: spec.SchemaProps{
							Description: "Runtime defines the serving runtime environment that will be used to execute the model. It is an inference service spec template that determines how the service should be deployed. Runtime is optional - if not defined, the operator will automatically select the best runtime based on the model's size, architecture, format, quantization, and framework.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.ServingRuntimeRef"),
						},
					},
					"router": {
						SchemaProps: spec.SchemaProps{
							Description: "Router defines the router spec",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.RouterSpec"),
						},
					},
					"kedaConfig": {
						SchemaProps: spec.SchemaProps{
							Description: "KedaConfig defines the autoscaling configuration for KEDA Provides settings for event-driven autoscaling using KEDA (Kubernetes Event-driven Autoscaling), allowing the service to scale based on custom metrics or event sources.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.KedaConfig"),
						},
					},
					"acceleratorSelector": {
						SchemaProps: spec.SchemaProps{
							Description: "AcceleratorSelector specifies accelerator selection preferences",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.AcceleratorSelector"),
						},
					},
					"traffic": {
						SchemaProps: spec.SchemaProps{
							Description: "Traffic configures the load-balancing policy applied to all HTTPRoutes OME emits for this InferenceService. See the TrafficSpec doc for details.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.TrafficSpec"),
						},
					},
					"rollout": {
						SchemaProps: spec.SchemaProps{
							Description: "Rollout is the single home for rollout configuration on this InferenceService: an ordered list of rollout groups, each polymorphic in its progression (canary | blueGreen | rollingUpdate). Sequencing is the group list order; a group's Components roll together.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.RolloutSpec"),
						},
					},
					"scalingPolicy": {
						SchemaProps: spec.SchemaProps{
							Description: "ScalingPolicy coordinates replica counts across Components when more than one autoscaler would otherwise drift (e.g., engine + decoder in a PD-disaggregated service that requires 1:1 sharding). When nil, every Component autoscales independently. Alpha. The API may change without notice.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.ScalingPolicy"),
						},
					},
					"placement": {
						SchemaProps: spec.SchemaProps{
							Description: "Placement declares how the multi-cluster control plane selects and orders the workload clusters this InferenceService is placed onto. When nil, the control plane falls back to the ome.io/accelerator-requirements and ome.io/cluster-selector annotations (unchanged legacy behavior). Only consulted on the control-plane cluster; ignored in single-cluster deployments. Alpha; the API may change without notice.",
							Ref:         ref("sigs.k8s.io/ome/pkg/apis/ome/v1beta1.PlacementSpec"),
						},
					},
				},
			},
		},
		Dependencies: []string{
			"sigs.k8s.io/ome/pkg/apis/ome/v1beta1.AcceleratorSelector", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.DecoderSpec", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.EngineSpec", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.KedaConfig", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.ModelRef", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.PlacementSpec", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.RolloutSpec", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.RouterSpec", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.ScalingPolicy", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.ServingRuntimeRef", "sigs.k8s.io/ome/pkg/apis/ome/v1beta1.TrafficSpec"},
	}
}

